chmod 700 "$bounded_fixture_dir"
printf 'AUN_BOUNDED_FIXTURE_ROOT=%s\n' "$bounded_fixture_dir" >> "$GITHUB_ENV"
node --input-type=module > bounded-ci-subject.json <<'JS'
import {readFileSync,createReadStream,mkdtempSync,openSync,closeSync,rmSync} from 'node:fs';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const gitOptions={timeout:15000,maxBuffer:16*1024*1024};

const event=JSON.parse(readFileSync(process.env.GITHUB_EVENT_PATH,'utf8'));
const tested_commit=git('rev-parse','HEAD'),candidate_head=event.pull_request?.head.sha??tested_commit;
const base=event.pull_request?.base.sha??'0f772883db6f3b50772d3e4b82ce47795091f0a9';
// Preserve the complete binary diff checksum without buffering the
// growing raw-evidence packet in execFileSync's stdout limit.
const diffDir=mkdtempSync(join(process.env.RUNNER_TEMP,'aun-subject-diff-'));
const diffPath=join(diffDir,'subject.diff'),diffFd=openSync(diffPath,'wx',0o600);
let binary_diff_sha256;
try {
  try {execFileSync('git',['diff','--binary','--full-index',`${base}...${candidate_head}`],{...gitOptions,stdio:['ignore',diffFd,'pipe']});}
  finally {closeSync(diffFd);}
  const digest=createHash('sha256');
  for await(const chunk of createReadStream(diffPath))digest.update(chunk);
  binary_diff_sha256=digest.digest('hex');
} finally {rmSync(diffDir,{recursive:true,force:true});}
const test_files_sha256=Object.fromEntries(['admission','admission_postgres','retry','use_trace'].map(n=>{
  const p=`tests/contract/test_queue_bounded_${n}.test.ts`;return[p,sha(readFileSync(p))];
}));
console.log(JSON.stringify({base,candidate_head,candidate_tree:git('rev-parse',`${candidate_head}^{tree}`),tested_commit,
  tested_tree:git('rev-parse','HEAD^{tree}'),tested_parents:git('rev-list','--parents','-n1','HEAD').split(' ').slice(1),
  binary_diff_sha256,test_files_sha256,
  design_raw_sha256:'ed86b14f35b97d8483bf8052dd73765732c4568a945cb6e59bc6b8b7e99ea703',
  design_canonical_sha256:'880b99e5514f9791968ba8971e9d526b59173732986c12a54e8db04413f1972e',
  run_id:process.env.GITHUB_RUN_ID,run_attempt:process.env.GITHUB_RUN_ATTEMPT,scope:'TESTED_CHECKOUT_OBSERVATION',private_status:'PRIVATE_STAGE_REQUIRED'}));
